/* From Uiverse.io by mrhyddenn - Tags: loader */
.__UIV_SCOPE__ .loader {
  position: relative;
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: linear-gradient(#ee280e, #15a0f7, #6ed15a);
  animation: animate7712 1.2s linear infinite;
}

@keyframes animate7712 {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}

.__UIV_SCOPE__ .loader span {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: linear-gradient(#ee280e, #15a0f7, #5ad15a);
}

.__UIV_SCOPE__ .loader:after {
  content: '';
  position: absolute;
  top: 10px;
  left: 10px;
  right: 10px;
  bottom: 10px;
  background: #333;
  border: solid #333 10px;
  border-radius: 50%;
}

.__UIV_SCOPE__ .loader span:nth-child(1) {
  filter: blur(5px);
}

.__UIV_SCOPE__ .loader span:nth-child(2) {
  filter: blur(10px);
}

.__UIV_SCOPE__ .loader span:nth-child(3) {
  filter: blur(25px);
}

.__UIV_SCOPE__ .loader span:nth-child(4) {
  filter: blur(50px);
}
